   "text": "这一章只要带走一句话：**量子形式体系里住着两个互相不相容的过程，而没人知道它们怎么共存。**\n把它们叫 U 和 R。U 是**幺正演化（unitary evolution）**，就是上一章的薛定谔方程：连续、确定、可逆。R 是**态缩减（state reduction）**，就是测量那一跳：不连续、随机、不可逆。\n问题不在于算不准，而在于：U 的框架里根本没有「只留下一个结果」这回事。它把所有可能性都留着，而且留得越来越整齐；R 却只给你一个结果，并且说不清依据什么挑。\n这一章把这个矛盾讲清楚，同时把量子力学的另外几件工具装上：希尔伯特空间与狄拉克记号、厄米算子与投影算子、零测量、自旋与旋量、以及自旋态所住的那个球面。"
