   "orig": "考虑 21.7 节讨论过的那种情形：单个光子射向分束器，态一部分被反射、一部分被透射。相遇之后，态就是这两个正交部分之和——透射部分 |t⟩ 与反射部分 |r⟩（为让它成为一个清爽的直和，我们把相对相位因子吸收进 |t⟩、|r⟩ 的定义，并且不坚持归一化）：|ψ⟩ = |t⟩ + |r⟩（见图 22.5）。假设在透射束里放一台探测器，为便于论证，设它有 100% 的探测效率；光子源也要做到每次发射都在源处被 100% 记录。（这显然是理想化；真实实验里很难逼近这样的效率。不过为了说明量子力学怎么运作，这样理想化是合理的。）如果发现有时候源已发出光子、探测器却没收到，那就可以断定：这一次光子「走了另一条路」，其态是反射态 |r⟩。可怪的是，这次「没探测到」的测量居然让光子的态发生了量子跳跃（从叠加态 |ψ⟩ 跳到反射态 |r⟩），而光子压根没和测量装置打过照面！这就是零测量的一个例子。",
