   "orig": "对光子来说，螺旋度态（具确定螺旋度的态）就是圆偏振态：s = 1 为右旋圆偏振，s = −1 为左旋圆偏振。光子还有其他偏振态，例如平面偏振，但它们不过是右旋态与左旋态的线性组合。这一切的几何我很快会在 22.9 节末尾谈到，现在用不着。眼下只需一条关于圆偏振在反射时如何表现的事实。设有处于圆偏振态的光子垂直射到分束器（或我们用的任何别的镜子）上，于是反射束径直沿来路返回。我们需要的事实是：反射光子的偏振态与源发出的光子相反，而透射部分的偏振与发出的光子相同。如果愿意，可以设想初始束方向有个极小的倾斜，免得反射光束又钻回源里。这不会实质影响我们的讨论。",
