   "h": "22.10 更高自旋：马约拉纳图景",
   "orig": "再举一例，说明量子力学里那些看似抽象的复数与空间几何关系之紧密：看自旋 j = n/2 的有质量粒子（或原子）的自旋态。如上（22.8 节）所说，它可用一个 n 指标对称旋量张量 ψ_{AB…F} 描述。有个定理断言：每个这样的旋量张量都有「典范分解」，可写成单指标旋量的对称化乘积，在尺度因子与次序的意义上唯一：ψ_{AB…F} = α_{(A}β_{B} ⋯ φ_{F)}。这里记得 12.7 节的约定：指标外加圆括号表示对称化。借用图 22.10 的图像——单指标旋量 ψ_A 在几何上由黎曼球上一点（即空间中一个方向）表示，差一个整体复因子——可以断定：旋量张量 ψ_{AB…F} 本身也能在黎曼球上表示，差一个整体尺度因子，表示为球上 n 个点的无序集合（即空间中 n 个无序方向）；见图 22.14。一般自旋 n 态的这种表示，称为马约拉纳描述（Majorana description）。它最初发现于 1932 年（用的却是另一种程序，22.11 节我会略作说明），发现者是才华出众的意大利物理学家埃托雷·马约拉纳。（31 岁那年，他从那不勒斯湾的一艘船上神秘失踪，也许是自杀。）",
